const PDF_CONFIRM_BYTES = 30 * 1024 * 1024;
const PDF_MAX_BYTES = 50 * 1024 * 1024; // 与后端 nginx client_max_body_size 50m 对齐，避免大文件上传被 413

// ═══════════════════════════════════════════════════════════════════
// HTTP helper (binary-safe)
// ═══════════════════════════════════════════════════════════════════

function resolveRectoHostNetwork() {
	// Electron net.fetch uses the host session/system proxy and supports real abort.
	// Resolve before sending; never replay a POST through a second transport.
	if (!process.versions?.electron) return null;
	try {
		const remote = require("electron").remote || require("@electron/remote");
		const Controller = remote.getGlobal("AbortController");
		if (typeof remote.net?.fetch === "function" && typeof Controller === "function") return { net: remote.net, Controller };
	} catch (_) {}
	throw Object.assign(new Error("Host network unavailable"), { code: "HOST_NETWORK_UNAVAILABLE", rectoUiKey: "error.hostNetwork" });
}

function requestRectoHostNetwork(host, url, method, body, headers, timeout, options) {
	return new Promise((resolve, reject) => {
		const parsed = new URL(url);
		if (!["https:", "http:"].includes(parsed.protocol)) throw new Error("Unsupported URL protocol");
		if (body && typeof body.pipe === "function") throw new Error("Host request requires a buffered body");
		const controller = new host.Controller();
		const maxBytes = Number(options.maxBytes) || 0;
		let settled = false, timer, status = null, reader;
		const cleanup = () => { clearTimeout(timer); options.signal?.removeEventListener("abort", onAbort); };
		const fail = error => {
			if (settled) return;
			settled = true; cleanup();
			if (status !== null) { error.httpStatus = status; error.responseReceived = true; }
			try { controller.abort(); } catch (_) {}
			try { if (reader) Promise.resolve(reader.cancel()).catch(() => {}); } catch (_) {}
			reject(error);
		};
		const onAbort = () => fail(new Error("任务已取消"));
		if (options.signal?.aborted) { onAbort(); return; }
		options.signal?.addEventListener("abort", onAbort, { once: true });
		const deadline = Number(options.deadlineMs) || Number(timeout) || 30000;
		timer = setTimeout(() => fail(Object.assign(new Error("Request deadline exceeded"), { code: "REQUEST_DEADLINE_EXCEEDED" })), deadline);
		timer.unref?.();
		const run = async () => {
			// Chromium sets framing and decodes gzip; never trust compressed length as
			// the decoded size limit. Explicit bearer headers survive credentials=omit.
			const cleanHeaders = Object.fromEntries(Object.entries(headers || {}).filter(([key]) => !/^(content-length|accept-encoding)$/i.test(key)));
			const response = await host.net.fetch(parsed.href, { method, headers: cleanHeaders, body: body == null ? undefined : body,
				signal: controller.signal, redirect: "error", credentials: "omit", cache: "no-store" });
			if (settled) return;
			status = response.status;
			const chunks = []; let total = 0;
			reader = response.body?.getReader();
			while (reader && !settled) {
				const chunk = await reader.read();
				if (settled) return;
				if (chunk.done) break;
				const bytes = Buffer.from(chunk.value); total += bytes.length;
				if (maxBytes && total > maxBytes) throw Object.assign(new Error("Response too large"), { code: "RESPONSE_TOO_LARGE" });
				chunks.push(bytes);
			}
			if (settled) return;
			const bodyBuffer = Buffer.concat(chunks);
			settled = true; cleanup();
			resolve({ status, bodyBuffer, bodyText: bodyBuffer.toString("utf-8") });
		};
		void run().catch(error => {
			if (status !== null && error.code !== "RESPONSE_TOO_LARGE") error.code = "RESPONSE_INTERRUPTED";
			fail(error);
		});
	});
}

function nativeRequest(url, method, body, headers, timeout, options = {}) {
	let host;
	try { host = resolveRectoHostNetwork(); } catch (error) { return Promise.reject(error); }
	if (host) return requestRectoHostNetwork(host, url, method, body, headers, timeout, options);
	return new Promise((resolve, reject) => {
		const p = new URL(url);
		if (p.protocol !== "https:" && p.protocol !== "http:")
			throw new Error(`Unsupported URL protocol: ${p.protocol}`);
		const mod = p.protocol === "https:" ? https : http;
		const h = { ...headers };
		const maxBytes = Number(options.maxBytes) || 0;
		const isStream = body && typeof body.pipe === "function";
		if (body && !isStream && !h["Content-Length"])
			h["Content-Length"] = Buffer.isBuffer(body) ? body.length : Buffer.byteLength(body);
		let settled = false;
		let req;
		let abortHandler;
		let streamErrorHandler;
		let deadlineTimer;
		let responseDecoder;
		let responseStatus = null;
		const requestError = (code, message, cause) => Object.assign(new Error(message), { code, ...(cause ? { cause } : {}) });
		const cleanup = () => {
			if (deadlineTimer) {
				clearTimeout(deadlineTimer);
				deadlineTimer = null;
			}
			if (options.signal && abortHandler) {
				options.signal.removeEventListener("abort", abortHandler);
				abortHandler = null;
			}
			if (isStream && streamErrorHandler && typeof body.removeListener === "function") {
				body.removeListener("error", streamErrorHandler);
				streamErrorHandler = null;
			}
		};
		const fail = (err) => {
			if (settled) return;
			settled = true;
			if (responseStatus !== null) { err.httpStatus = responseStatus; err.responseReceived = true; }
			if (isStream && typeof body.destroy === "function") body.destroy();
			if (responseDecoder && typeof responseDecoder.destroy === "function") responseDecoder.destroy();
			if (req) req.destroy();
			cleanup();
			reject(err);
		};
		const finish = (value) => {
			if (settled) return;
			settled = true;
			cleanup();
			resolve(value);
		};
		if (options.signal && options.signal.aborted) {
			fail(new Error("任务已取消"));
			return;
		}
		const explicitDeadlineMs = Number(options.deadlineMs) || 0;
		if (explicitDeadlineMs > 0) {
			deadlineTimer = setTimeout(() => fail(requestError("REQUEST_DEADLINE_EXCEEDED", "Request deadline exceeded")), explicitDeadlineMs);
			if (typeof deadlineTimer.unref === "function") deadlineTimer.unref();
		}
		req = mod.request({
			hostname: p.hostname, port: p.port || (p.protocol === "https:" ? 443 : 80),
			path: p.pathname + p.search, method, headers: h,
		}, (res) => {
			responseStatus = res.statusCode;
			const chunks = [];
			let total = 0;
			res.on("aborted", () => fail(requestError("RESPONSE_INTERRUPTED", "Response interrupted")));
			res.on("error", error => fail(requestError("RESPONSE_INTERRUPTED", "Response interrupted", error)));
			res.on("close", () => { if (!res.complete) fail(requestError("RESPONSE_INTERRUPTED", "Response interrupted")); });
			res.on("data", (c) => {
				if (settled) return;
				total += c.length;
				if (maxBytes && total > maxBytes) {
					fail(requestError("RESPONSE_TOO_LARGE", `Response too large: ${total} bytes > ${maxBytes} bytes`));
					return;
				}
				chunks.push(c);
			});
			res.on("end", () => {
				if (settled) return;
				const wireBuffer = Buffer.concat(chunks);
				const encoding = String(res.headers["content-encoding"] || "").trim().toLowerCase();
				const finishBuffer = buf => {
					if (settled) return;
					if (maxBytes && buf.length > maxBytes) {
						fail(requestError("RESPONSE_TOO_LARGE", `Response too large: ${buf.length} bytes > ${maxBytes} bytes`));
						return;
					}
					finish({ status: res.statusCode, bodyBuffer: buf, bodyText: buf.toString("utf-8") });
				};
				if (!options.decompressResponse || !encoding || encoding === "identity") {
					finishBuffer(wireBuffer);
					return;
				}
				if (encoding !== "gzip") {
					fail(requestError("RESPONSE_ENCODING_UNSUPPORTED", "Unsupported Content-Encoding"));
					return;
				}
				const decodedChunks = [];
				let decodedBytes = 0;
				responseDecoder = zlib.createGunzip();
				responseDecoder.on("data", chunk => {
					if (settled) return;
					decodedBytes += chunk.length;
					if (maxBytes && decodedBytes > maxBytes) {
						fail(requestError("RESPONSE_TOO_LARGE", `Response too large: ${decodedBytes} bytes > ${maxBytes} bytes`));
						return;
					}
					decodedChunks.push(chunk);
				});
				responseDecoder.on("error", error => fail(requestError("RESPONSE_DECOMPRESSION_FAILED", "Response decompression failed", error)));
				responseDecoder.on("end", () => finishBuffer(Buffer.concat(decodedChunks)));
				responseDecoder.end(wireBuffer);
			});
		});
		abortHandler = () => fail(new Error("任务已取消"));
		if (options.signal) options.signal.addEventListener("abort", abortHandler, { once: true });
		if (timeout) req.setTimeout(timeout, () => fail(requestError("REQUEST_TIMEOUT", "Request timeout")));
		req.on("error", fail);
		if (isStream) {
			streamErrorHandler = fail;
			body.on("error", streamErrorHandler);
			body.pipe(req);
		} else {
			if (body) req.write(body);
			req.end();
		}
	});
}





async function hashFileSha256(filePath, signal = null) {
	return await new Promise((resolve, reject) => {
		const hash = crypto.createHash("sha256");
		const stream = fs.createReadStream(filePath);
		let settled = false;
		const cleanup = () => {
			if (signal) signal.removeEventListener("abort", onAbort);
		};
		const finish = (callback, value) => {
			if (settled) return;
			settled = true;
			cleanup();
			callback(value);
		};
		const onAbort = () => {
			stream.destroy();
			finish(reject, new Error("任务已取消"));
		};
		stream.on("data", chunk => hash.update(chunk));
		stream.on("error", error => finish(reject, error));
		stream.on("end", () => finish(resolve, hash.digest("hex")));
		if (signal) {
			signal.addEventListener("abort", onAbort, { once: true });
			if (signal.aborted) onAbort();
		}
	});
}

