		publicCode: /^[A-Z][A-Z0-9_]{1,79}$/.test(error.backendErrorCode || "") ? error.backendErrorCode : "unknown",
		uiKey: Object.prototype.hasOwnProperty.call(RECTO_UI_MESSAGES.en, error.rectoUiKey || "") ? error.rectoUiKey : "unknown", frames,
